showItem(
  "mailContext-forwardAsAttachment",
  !onSpecialItem &&
    numSelectedMessages &&
    isCommandEnabled("cmd_forwardAttachment")
);

if (isDummyMessage || onSpecialItem) {
  showItem("mailContext-tags", false);
} else {
  showItem("mailContext-tags", true);
  this._initMessageTags();
}
